import React, { useEffect, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";

function MapView() {
  const [revendas, setRevendas] = useState([]);
  const [meta, setMeta] = useState({ progresso: 0, ultimaAtualizacao: null });
  const [position, setPosition] = useState([-23.55, -46.63]); // Default SP

  // Filtros
  const [ufSelecionada, setUfSelecionada] = useState("");
  const [municipioSelecionado, setMunicipioSelecionado] = useState("");
  const [cnpjFiltro, setCnpjFiltro] = useState("");
  const [revendasFiltradas, setRevendasFiltradas] = useState([]);

  // Pedir localização ao utilizador
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setPosition([pos.coords.latitude, pos.coords.longitude]);
        },
        () => console.log("⚠️ Localização negada, usando posição padrão.")
      );
    }
  }, []);

  // Buscar revendas
  useEffect(() => {
    fetch("http://localhost:5000/api/revendas")
      .then((res) => res.json())
      .then((data) => {
        setRevendas(data);
        setRevendasFiltradas(data);
      });
  }, []);

  // Atualizar progresso/meta
  useEffect(() => {
    const interval = setInterval(() => {
      fetch("http://localhost:5000/api/meta")
        .then((res) => res.json())
        .then((data) => setMeta(data));
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  // Extrair lista única de UFs
  const ufs = [...new Set(revendas.map((r) => r.uf))].sort();
  // Extrair lista única de municípios pela UF
  const municipios = ufSelecionada
    ? [...new Set(revendas.filter((r) => r.uf === ufSelecionada).map((r) => r.municipio))].sort()
    : [];

  // Função para aplicar filtros
  const aplicarFiltros = () => {
    let filtradas = revendas;

    if (ufSelecionada) {
      filtradas = filtradas.filter((r) => r.uf === ufSelecionada);
    }
    if (municipioSelecionado) {
      filtradas = filtradas.filter((r) => r.municipio === municipioSelecionado);
    }
    if (cnpjFiltro) {
      filtradas = filtradas.filter((r) => r.cnpj.includes(cnpjFiltro));
    }

    setRevendasFiltradas(filtradas);

    // Reposicionar mapa se tiver resultados
    if (filtradas.length > 0 && filtradas[0].latitude && filtradas[0].longitude) {
      setPosition([filtradas[0].latitude, filtradas[0].longitude]);
    }
  };

  return (
    <div style={{ position: "relative", height: "100vh", width: "100%" }}>
      {/* Painel informativo */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          right: "10px",
          background: "rgba(255,255,255,0.9)",
          padding: "10px",
          borderRadius: "8px",
          fontSize: "12px",
          zIndex: 1000,
          minWidth: "220px",
        }}
      >
        {meta.ultimaAtualizacao ? (
          <div>
            <strong>Última atualização:</strong>{" "}
            {new Date(meta.ultimaAtualizacao).toLocaleString("pt-BR")}
          </div>
        ) : (
          <div>Atualização em andamento...</div>
        )}

        {meta.progresso < 100 ? (
          <div style={{ marginTop: "8px" }}>
            <div>Decodificação: {meta.progresso}%</div>
            <div
              style={{
                width: "100%",
                background: "#ddd",
                borderRadius: "5px",
                overflow: "hidden",
                marginTop: "4px",
              }}
            >
              <div
                style={{
                  width: `${meta.progresso}%`,
                  height: "8px",
                  background: "#4caf50",
                }}
              />
            </div>
          </div>
        ) : (
          <button
            style={{
              marginTop: "10px",
              padding: "5px 10px",
              border: "none",
              borderRadius: "5px",
              background: "#007bff",
              color: "#fff",
              cursor: "pointer",
            }}
            onClick={() => window.location.reload()}
          >
            🔄 Recarregar novos dados
          </button>
        )}
      </div>

      {/* Painel de filtros */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          left: "10px",
          background: "rgba(255,255,255,0.9)",
          padding: "10px",
          borderRadius: "8px",
          fontSize: "12px",
          zIndex: 1000,
          minWidth: "250px",
        }}
      >
        <div>
          <label>UF:</label>
          <select value={ufSelecionada} onChange={(e) => setUfSelecionada(e.target.value)}>
            <option value="">Todas</option>
            {ufs.map((uf) => (
              <option key={uf} value={uf}>
                {uf}
              </option>
            ))}
          </select>
        </div>

        <div style={{ marginTop: "8px" }}>
          <label>Município:</label>
          <select
            value={municipioSelecionado}
            onChange={(e) => setMunicipioSelecionado(e.target.value)}
            disabled={!ufSelecionada}
          >
            <option value="">Todos</option>
            {municipios.map((m) => (
              <option key={m} value={m}>
                {m}
              </option>
            ))}
          </select>
        </div>

        <div style={{ marginTop: "8px" }}>
          <label>CNPJ:</label>
          <input
            type="text"
            value={cnpjFiltro}
            onChange={(e) => setCnpjFiltro(e.target.value)}
            placeholder="Digite o CNPJ"
            style={{ width: "100%" }}
          />
        </div>

        <button
          style={{
            marginTop: "10px",
            padding: "5px 10px",
            border: "none",
            borderRadius: "5px",
            background: "#28a745",
            color: "#fff",
            cursor: "pointer",
          }}
          onClick={aplicarFiltros}
        >
          Aplicar filtros
        </button>
      </div>

      {/* Mapa */}
      <MapContainer
        center={position}
        zoom={10}
        style={{ height: "100%", width: "100%" }}
      >
        <TileLayer
          attribution="&copy; OpenStreetMap"
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        {revendasFiltradas
          .filter((r) => r.latitude && r.longitude)
          .map((r, idx) => (
            <Marker key={idx} position={[r.latitude, r.longitude]}>
              <Popup>
                <b>{r.razao_social}</b> <br />
                {r.rua}, {r.bairro}, {r.municipio}/{r.uf} <br />
                CNPJ: {r.cnpj} <br />
                <a
                  href={`https://waze.com/ul?ll=${r.latitude},${r.longitude}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Abrir no Waze
                </a>{" "}
                |{" "}
                <a
                  href={`https://www.google.com/maps?q=${r.latitude},${r.longitude}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Abrir no Maps
                </a>
              </Popup>
            </Marker>
          ))}
      </MapContainer>
    </div>
  );
}

export default MapView;
